package com.brightnest.app.ui

data class Story(
    val id: String,
    val emoji: String,
    val titleEn: String,
    val titleUr: String,
    val titleAr: String = "",
    val titleHi: String = "",
    val taglineEn: String,
    val taglineUr: String,
    val taglineAr: String = "",
    val taglineHi: String = "",
    val lessonEn: String,
    val lessonUr: String,
    val lessonAr: String = "",
    val lessonHi: String = "",
    val contentEn: String,
    val contentUr: String,
    val contentAr: String = "",
    val contentHi: String = ""
) {
    fun getLocalizedTitle(langCode: String): String {
        return when (langCode.lowercase()) {
            "ur" -> titleUr.ifEmpty { titleEn }
            "ar" -> titleAr.ifEmpty { titleUr.ifEmpty { titleEn } }
            "hi" -> titleHi.ifEmpty { titleEn }
            else -> titleEn
        }
    }

    fun getLocalizedTagline(langCode: String): String {
        return when (langCode.lowercase()) {
            "ur" -> taglineUr.ifEmpty { taglineEn }
            "ar" -> taglineAr.ifEmpty { taglineUr.ifEmpty { taglineEn } }
            "hi" -> taglineHi.ifEmpty { taglineEn }
            else -> taglineEn
        }
    }

    fun getLocalizedLesson(langCode: String): String {
        return when (langCode.lowercase()) {
            "ur" -> lessonUr.ifEmpty { lessonEn }
            "ar" -> lessonAr.ifEmpty { lessonUr.ifEmpty { lessonEn } }
            "hi" -> lessonHi.ifEmpty { lessonEn }
            else -> lessonEn
        }
    }

    fun getLocalizedContent(langCode: String): String {
        return when (langCode.lowercase()) {
            "ur" -> contentUr.ifEmpty { contentEn }
            "ar" -> contentAr.ifEmpty { contentUr.ifEmpty { contentEn } }
            "hi" -> contentHi.ifEmpty { contentEn }
            else -> contentEn
        }
    }
}

