            lessonAr = "الإيمان الصادق يثبت أمام أصعب المحن والاختبارات.",
            lessonHi = "सच्चा ईमान सबसे कठिन परीक्षा में भी मज़बूत रहता है।",
            contentEn = "Prophet Ibrahim (Abraham) lived among people who worshipped statues of stone and wood. Even his own father, Azar, carved idols and sold them. But from a young age Ibrahim knew that statues could not hear, see, eat, or help anyone. He believed in only one true God — Allah — the Creator of the sun, the moon, and the stars.\n\nIbrahim politely asked his father, his uncles, and the king to leave the worship of idols and worship Allah alone. They became angry. So one day, while everyone was away at a big festival, Ibrahim went into the temple. He broke every idol with an axe — except the biggest one — and hung the axe on its shoulder.\n\nWhen the people returned and saw their broken idols, they were furious. They demanded, 'Who did this to our gods?' Ibrahim calmly said, 'Ask the big one — if it can speak!' The people stood quiet for a moment, realizing that statues truly could do nothing. But instead of believing, they grew even more angry. They built the biggest fire anyone had ever seen and threw Ibrahim into it.\n\nAt that moment Allah commanded, 'O fire, be coolness and safety upon Ibrahim.' The flames could not burn him. He walked out completely unharmed, while the disbelievers stood in shock.\n\nIbrahim spent the rest of his life teaching tawhid — that Allah is One. He traveled with his son Ismail to Makkah and together they built the holy Kaaba. Allah loved Ibrahim so much that He called him 'Khalilullah' — the Friend of Allah.",
            contentUr = "حضرت ابراہیم علیہ السلام ایسے لوگوں میں رہتے تھے جو پتھر اور لکڑی کے بتوں کی پوجا کرتے تھے۔ ان کے اپنے والد آزر بھی بت تراش کر بیچتے تھے۔ مگر ابراہیم بچپن سے جانتے تھے کہ یہ بت نہ سن سکتے ہیں، نہ دیکھ سکتے ہیں، نہ کھا سکتے ہیں اور نہ کسی کا کچھ بھلا کر سکتے ہیں۔ آپ صرف ایک سچے معبود — اللہ — پر ایمان رکھتے تھے، جو سورج، چاند اور ستاروں کا خالق ہے۔\n\nابراہیم نے اپنے والد، چچا اور بادشاہ سے بڑے ادب سے کہا کہ بتوں کی پوجا چھوڑ کر صرف اللہ کی عبادت کریں۔ وہ سب غصے میں آ گئے۔ ایک دن جب سب لوگ بڑے میلے میں چلے گئے تو ابراہیم بت خانے میں گئے اور کلہاڑی سے ہر چھوٹے بت کو توڑ ڈالا، صرف بڑے بت کو چھوڑ دیا اور کلہاڑی اسی کے کندھے پر لٹکا دی۔\n\nجب لوگ واپس آئے اور ٹوٹے ہوئے بت دیکھے تو غصے سے بپھر گئے۔ پوچھنے لگے: 'یہ کس نے کیا؟' ابراہیم نے سکون سے فرمایا: 'بڑے بت سے پوچھ لو، اگر یہ بول سکتا ہے!' ایک لمحے کو سب خاموش ہو گئے کہ واقعی بت کچھ نہیں کر سکتے، مگر ماننے کے بجائے اور بھڑک اٹھے۔ انہوں نے ایک بہت بڑی آگ جلائی اور ابراہیم کو اس میں پھینک دیا۔\n\nاسی لمحے اللہ نے حکم دیا: 'اے آگ! ابراہیم پر ٹھنڈی اور سلامتی والی ہو جا۔' آگ انہیں جلا نہ سکی، آپ بالکل صحیح سلامت باہر نکل آئے اور کافر حیران رہ گئے۔\n\nباقی پوری زندگی ابراہیم نے توحید کا درس دیا۔ آپ اپنے بیٹے اسماعیلؑ کے ساتھ مکہ تشریف لے گئے اور دونوں نے مل کر بیت اللہ (کعبہ) کی تعمیر کی۔ اللہ کو ابراہیم اتنے پیارے تھے کہ اس نے انہیں 'خلیل اللہ' — اللہ کا دوست — کہا۔",
            contentAr = "عاش إبراهيم عليه السلام وسط قوم يعبدون الأصنام المصنوعة من الحجر والخشب، وكان والده آزر ينحت تلك الأصنام ويبيعها. لكن إبراهيم أدرك منذ صغره أن هذه الأصنام لا تسمع ولا تبصر ولا تنفع ولا تضر، وآمن بالله الواحد الأحد، خالق الشمس والقمر والنجوم.\n\nدعا إبراهيم والده وقومه بالحكمة واللين لترك الأصنام وعبادة الله، فغضبوا منه. وفي أحد أيام عيدهم، دخل إبراهيم المعبد وحطم كل الأصنام بفأس إلا كبيرهم، وعلق الفأس على كتفه.\n\nفلما عاد القوم ورأوا أصنامهم محطمة غضبوا وقالوا: 'من فعل هذا بآلهتنا؟' أجاب إبراهيم بهدوء: 'اسألوا كبيرهم هذا إن كانوا ينطقون!' أدرك القوم في أنفسهم عجز أصنامهم، لكن كبرياءهم دفعهم لإشعال نار عظيمة وإلقاء إبراهيم فيها.\n\nحينها أمر الله تعالى: 'يَا نَارُ كُونِي بَرْداً وَسَلَاماً عَلَى إِبْرَاهِيمَ'. فلم تحرق النار سوى قيوده، وخرج منها سليماً معافى وسط ذهول الكافرين.\n\nقضى إبراهيم حياته يدعو إلى التوحيد، وسافر مع ابنه إسماعيل إلى مكة وبنيا معاً الكعبة المشرفة. وقد أحبه الله حباً شديداً واتخذه خليلاً.",
            contentHi = "हज़रत इब्राहिम (अलैहिस्सलाम) ऐसे लोगों के बीच रहते थे जो पत्थर और लकड़ी की मूर्तियों की पूजा करते थे। उनके पिता आज़र भी मूर्तियाँ बनाते और बेचते थे। लेकिन इब्राहिम बचपन से जानते थे कि मूर्तियाँ न सुन सकती हैं, न देख सकती हैं, न खा सकती हैं और न किसी की मदद कर सकती हैं। वह सिर्फ़ एक सच्चे ईश्वर — अल्लाह — पर ईमान रखते थे, जो सूरज, चाँद और सितारों का बनाने वाला है।\n\nइब्राहिम ने अपने पिता और राजा से बहुत अदब से कहा कि मूर्तियों की पूजा छोड़कर सिर्फ़ अल्लाह की इबादत करें। वे सब गुस्सा हो गए। एक दिन जब सभी लोग एक बड़े मेले में गए हुए थे, तो इब्राहिम मंदिर में गए और कुल्हाड़ी से हर छोटी मूर्ति को तोड़ दिया, सिर्फ़ बड़ी मूर्ति को छोड़ दिया और कुल्हाड़ी उसी के कंधे पर टाँग दी।\n\nजब लोग वापस आए और टूटी हुई मूर्तियाँ देखीं तो बहुत गुस्सा हुए। उन्होंने पूछा: 'हमारी मूर्तियों के साथ ऐसा किसने किया?' इब्राहिम ने शांति से कहा: 'बड़ी मूर्ति से पूछ लो, अगर यह बोल सकती है!' एक पल के लिए सब चुप हो गए कि मूर्तियाँ वास्तव में कुछ नहीं कर सकतीं, मगर मानने के बजाय और भड़क उठे। उन्होंने एक बहुत बड़ी आग जलाई और इब्राहिम को उसमें फेंक दिया।\n\nउसी समय अल्लाह ने आदेश दिया: 'ऐ आग! इब्राहिम पर ठंडी और सुरक्षा वाली हो जा।' आग उन्हें जला नहीं सकी, वह बिल्कुल सुरक्षित बाहर निकल आए और काफ़िर हैरान रह गए।\n\nइब्राहिम ने अपना पूरा जीवन अल्लाह की एकता (तौहीद) का संदेश देने में बिताया। वह अपने बेटे इस्माइल के साथ मक्का गए और दोनों ने मिलकर पवित्र काबा का निर्माण किया। अल्लाह को इब्राहिम इतने प्यारे थे कि उसने उन्हें 'खलील-उल्लाह' (अल्लाह का मित्र) कहा।"
        ),
        Story(
            id = "yusuf",
            emoji = "🌙",
            titleEn = "Prophet Yusuf",
            titleUr = "حضرت یوسف علیہ السلام",
            titleAr = "نبي الله يوسف عليه السلام",
            titleHi = "पैगंबर यूसुफ (अलैहिस्सलाम)",
            taglineEn = "The Boy Who Interpreted Dreams",
            taglineUr = "خوابوں کی تعبیر بتانے والے",
            taglineAr = "مفسر الأحلام والصديق الأمين",
            taglineHi = "सपनों का अर्थ बताने वाले",
            lessonEn = "Allah's plan is always better — even when things feel unfair.",
            lessonUr = "اللہ کا منصوبہ ہمیشہ بہتر ہوتا ہے، چاہے ابھی بات مشکل لگے۔",
            lessonAr = "تدبير الله دائماً أفضل، مهما بدت الظروف صعبة ومؤلمة.",
            lessonHi = "अल्लाह की योजना हमेशा बेहतर होती है, चाहे अभी परिस्थितियाँ कठिन लगें।",
            contentEn = "Prophet Yusuf (Joseph) was the beloved son of Prophet Yaqub. As a young boy, Yusuf had a beautiful dream — eleven stars, the sun, and the moon all bowed down to him. His wise father told him not to tell his brothers, because they would become jealous.\n\nYusuf's eleven brothers were already jealous of how much their father loved him. They made a wicked plan: they took Yusuf far away and threw him into a deep, dark well. Then they put fake blood on his shirt and told their father a wolf had eaten him.\n\nA passing caravan stopped to draw water and found Yusuf in the well. They sold him as a slave in Egypt to a nobleman called Al-Aziz. Yusuf grew up strong, handsome, and incredibly honest. When the nobleman's wife tried to lead him into wrong, Yusuf refused and ran. He was wrongly thrown into prison — yet even there he taught the other prisoners about Allah.\n\nAllah gave Yusuf a special gift: he could interpret dreams. In prison, he correctly told two men what their dreams meant. Years later, the King of Egypt had a strange dream about seven fat cows being eaten by seven thin cows. Yusuf explained: seven years of good harvest would come, followed by seven years of famine. He told them to save grain.\n\nThe king was so impressed he made Yusuf the chief minister of Egypt. When the famine came, people from many lands traveled to Egypt for food. One day, his own brothers came begging — not recognizing the brother they had thrown into a well. Yusuf forgave them with tears, brought his whole family to Egypt, and his childhood dream finally came true.",
            contentUr = "حضرت یوسف علیہ السلام حضرت یعقوبؑ کے بہت پیارے بیٹے تھے۔ بچپن میں یوسف نے ایک خوبصورت خواب دیکھا کہ گیارہ ستارے، سورج اور چاند ان کو سجدہ کر رہے ہیں۔ ان کے دانا والد نے فرمایا: یہ خواب اپنے بھائیوں کو نہ بتانا، ورنہ وہ حسد کریں گے۔\n\nیوسف کے گیارہ بھائی پہلے ہی اپنے والد کی محبت پر جلتے تھے۔ انہوں نے بری چال چلی: یوسف کو دور لے گئے اور ایک گہرے، اندھیرے کنویں میں ڈال دیا۔ پھر ان کی قمیض پر جھوٹا خون لگا کر والد کو کہا کہ بھیڑیا کھا گیا۔\n\nایک قافلہ پانی بھرنے رکا اور یوسف کو کنویں سے نکال لیا۔ انہوں نے یوسف کو مصر میں ایک امیر شخص 'العزیز' کے ہاتھ غلام بنا کر بیچ دیا۔ یوسف بڑے ہوئے تو خوبصورت، طاقتور اور بہت سچے انسان تھے۔ جب عزیز کی بیوی نے انہیں برائی پر مجبور کرنا چاہا تو آپ نے انکار کیا اور بھاگ نکلے۔ اس پر آپ کو بے قصور جیل میں ڈال دیا گیا، مگر وہاں بھی آپ دوسرے قیدیوں کو اللہ کا پیغام دیتے رہے۔\n\nاللہ نے یوسف کو خوابوں کی تعبیر کا خاص علم دیا تھا۔ جیل میں دو قیدیوں کے خوابوں کی صحیح تعبیر بتائی۔ کئی سال بعد بادشاہِ مصر نے ایک عجیب خواب دیکھا کہ سات موٹی گائیں ہیں اور سات دبلی گائیں انہیں کھا رہی ہیں۔ یوسف نے سمجھایا: 'سات سال خوب فصل ہو گی، پھر سات سال قحط آئے گا، اس لیے اناج جمع کرو۔'\n\nبادشاہ اتنا متاثر ہوا کہ یوسف کو پورے مصر کا وزیرِ خزانہ بنا دیا۔ جب قحط آیا تو دور دور سے لوگ مصر اناج لینے آنے لگے۔ ایک دن ان کے اپنے بھائی بھی غلہ لینے آئے — انہیں پہچانے بغیر جنہیں انہوں نے کنویں میں ڈالا تھا۔ یوسف نے آنسوؤں کے ساتھ سب کو معاف کیا، اپنے سب گھر والوں کو مصر بلا لیا، اور بچپن کا خواب پورا ہو گیا۔",
            contentAr = "كان يوسف عليه السلام الابن المحبب ليعقوب عليه السلام. رأى في صغره رؤيا عجيبة: أحد عشر كوكباً والشمس والقمر يسجدون له. أدرك أبوه يعقوب عظم الرؤيا ونصح يوسف بألا يقصها على إخوته خوفاً من حسدهم.\n\nاشتعل الحسد في قلوب إخوة يوسف، فدبروا مكيدة وألقوه في بئر مظلمة، ثم عادوا إلى أبيهم بقميصه ملطخاً بدم كذب مدعين أن الذئب قد أكله.\n\nمرت قافلة بالبئر فأخرجوا يوسف وباعوه في مصر للوزير (العزيز). نشأ يوسف شاباً في غاية الجمال والأمانة. وعندما راودته امرأة العزيز عن نفسه رفض واعتصم بالله، فأُدخل السجن ظلماً، ولكنه استمر هناك يدعو السجناء إلى توحيد الله.\n\nوهب الله يوسف علم تفسير الأحلام. وفي السجن فسر رؤيا سجينين بصدق. وبعد سنوات رأى ملك مصر رؤيا غريبة عن سبع بقرات سمان يأكلهن سبع عجاف. فسر يوسف الرؤيا بأن البلاد ستشهد سبع سنوات من الخصب تليها سبع سنوات من الجفاف الشديد، ونصحهم بطريقة حفظ الغلال.\n\nأعجب الملك بحكمة يوسف وعينه أميناً على خزائن مصر. وعندما حل الجفاف، جاء إخوة يوسف يطلبون الطعام دون أن يعرفوه. كشف يوسف عن نفسه وعفا عنهم عفواً كريماً، وجمع شمل الأسرة في مصر، وتحققت رؤياه التي رآها في صغره.",
            contentHi = "हज़रत यूसुफ (अलैहिस्सलाम) पैगंबर याकूब के बहुत प्यारे बेटे थे। बचपन में यूसुफ ने एक खूबसूरत सपना देखा कि ग्यारह तारे, सूरज और चाँद उन्हें सजदा कर रहे हैं। उनके बुद्धिमान पिता ने कहा कि यह सपना अपने भाइयों को मत बताना, वरना वे जलन करेंगे।\n\nयूसुफ के ग्यारह भाई पहले से ही अपने पिता के प्यार से जलते थे। उन्होंने एक बुरी योजना बनाई: वे यूसुफ को दूर ले गए और एक गहरे, अंधेरे कुएँ में फेंक दिया। फिर उनकी कमीज़ पर झूठा खून लगाकर पिता से कहा कि भेड़िया खा गया।\n\nएक गुज़रते हुए काफ़िले ने पानी भरने के लिए कुएँ में बाल्टी डाली और यूसुफ को बाहर निकाल लिया। उन्होंने यूसुफ को मिस्र के एक अमीर मंत्री 'अल-अज़ीज़' को गुलाम बनाकर बेच दिया। यूसुफ बड़े हुए तो बहुत सुंदर और ईमानदार थे। जब मंत्री की पत्नी ने उन्हें बुराई की ओर ले जाना चाहा तो उन्होंने इनकार किया। उन्हें बेगुनाह जेल में डाल दिया गया, लेकिन वहाँ भी वह दूसरे कैदियों को अल्लाह का संदेश देते रहे।\n\nअल्लाह ने यूसुफ को सपनों का अर्थ (तअबीर) बताने का विशेष ज्ञान दिया था। जेल में दो कैदियों के सपनों का सही अर्थ बताया। कई साल बाद मिस्र के राजा ने एक अजीब सपना देखा कि सात मोटी गायें हैं और सात दुबली गायें उन्हें खा रही हैं। यूसुफ ने समझाया: 'सात साल बहुत अच्छी फ़सल होगी, फिर सात साल अकाल पड़ेगा, इसलिए अनाज जमा करो।'\n\nराजा इतना प्रभावित हुआ कि उसने यूसुफ को पूरे मिस्र का खज़ांची (वित्त मंत्री) बना दिया। जब अकाल पड़ा तो दूर-दूर से लोग अनाज लेने आने लगे। एक दिन उनके अपने भाई भी अनाज लेने आए — बिना पहचाने कि यह वही भाई है जिसे कुएँ में फेंका था। यूसुफ ने आँसुओं के साथ सबको माफ़ कर दिया, अपने पूरे परिवार को मिस्र बुला लिया, और बचपन का सपना पूरा हो गया।"
        ),
        Story(
